const resposta = $input.first().json;
const notices = resposta.notices || [];
return notices
  .filter(n => n.prazo_status === 'pendente' && n.idprocessos != null)
  .map(n => ({
    json: {
      id_notice: n.id,
      id_processo: n.idprocessos,
      numero_processo: n.numero_processo,
      tribunal: n.tribunal,
      partes: n.partes,
      tipo: n.tipo,
      teor: n.teor,
      data_disponibilizacao: n.data_disponibilizacao,
    }
  }));

function ehIntimacaoDeAudiencia(tipo, teor) {
  const palavras = ['audiência', 'audiencia'];
  if (tipo) {
    const t = tipo.toLowerCase();
    return palavras.some(p => t.includes(p));
  }
  const txt = (teor || '').toLowerCase();
  return palavras.some(p => txt.includes(p));
}

function contemDesignacaoPericia(teor) {
  const txt = (teor || '').toLowerCase();
  return ['perícia', 'pericia', 'pericial'].some(p => txt.includes(p));
}

const item = $json;
return {
  json: {
    ...item,
    eh_audiencia: ehIntimacaoDeAudiencia(item.tipo, item.teor),
    tem_pericia: contemDesignacaoPericia(item.teor),
  }
};

const original = $('Classificar intimação').item.json;
const respostaIA = $json;
const texto = (respostaIA.content && respostaIA.content[0]) ? respostaIA.content[0].text : '{}';
let decisao;
try {
  decisao = JSON.parse(texto);
} catch (e) {
