function pascoa(ano) {
  const a = ano % 19, b = Math.floor(ano / 100), c = ano % 100;
  const d = Math.floor(b / 4), e = b % 4, f = Math.floor((b + 8) / 25);
  const g = Math.floor((b - f + 1) / 3), h = (19 * a + b - d - g + 15) % 30;
  const i = Math.floor(c / 4), k = c % 4;
  const l = (32 + 2 * e + 2 * i - h - k) % 7;
  const m = Math.floor((a + 11 * h + 22 * l) / 451);
  const mes = Math.floor((h + l - 7 * m + 114) / 31);
  const dia = ((h + l - 7 * m + 114) % 31) + 1;
  return new Date(Date.UTC(ano, mes - 1, dia));
}

function fmt(d) { return d.toISOString().slice(0, 10); }
function addDays(dateStr, n) { return fmt(new Date(new Date(dateStr + 'T00:00:00Z').getTime() + n * 86400000)); }

function feriadosNacionais(ano, incluirCarnaval) {
  const p = pascoa(ano);
  const feriados = new Set([
    ano + '-01-01', ano + '-04-21', ano + '-05-01', ano + '-09-07',
    ano + '-10-12', ano + '-11-02', ano + '-11-15', ano + '-12-25',
    fmt(new Date(p.getTime() - 2 * 86400000)),
  ]);
  if (ano >= 2024) feriados.add(ano + '-11-20');
  if (incluirCarnaval) {
    const segundaStr = fmt(new Date(p.getTime() - 48 * 86400000));
    feriados.add(segundaStr);
    feriados.add(addDays(segundaStr, 1));
  }
  return feriados;
}

// Dados pesquisados e citados (ver docs/CALENDARIOS_FORENSES.md no repositório Python).
// Cobre só TJSC e TRT12 para 2026 — qualquer outro tribunal/ano fica com
// calendario_confirmado=false, usando só feriados nacionais.
const FERIADOS_TJSC_2026 = ['2026-04-02', '2026-06-04', '2026-05-25'];
const FERIADOS_TRT12_2026 = ['2026-08-10', '2026-10-30', '2026-12-07'];

function suspensaoPrazosTjscTrt12(ano) {
  const dias = [];
  let d = ano + '-12-20';
  const fimAno = ano + '-12-31';
  while (d <= fimAno) { dias.push(d); d = addDays(d, 1); }
  d = (ano + 1) + '-01-01';
  const fim = (ano + 1) + '-01-20';
  while (d <= fim) { dias.push(d); d = addDays(d, 1); }
  return dias;
}

function calendarioParaTribunal(tribunal, anos) {
  const normalizado = (tribunal || '').toUpperCase().replace(/[\s-]/g, '');
  const feriados = new Set();
  anos.forEach(ano => feriadosNacionais(ano, true).forEach(f => feriados.add(f)));
  let confirmado = false;
  if (normalizado.includes('TJSC')) {
    FERIADOS_TJSC_2026.forEach(f => feriados.add(f));
    anos.forEach(ano => suspensaoPrazosTjscTrt12(ano).forEach(f => feriados.add(f)));
    confirmado = true;
  } else if (normalizado.includes('TRT12')) {
    FERIADOS_TRT12_2026.forEach(f => feriados.add(f));
    anos.forEach(ano => suspensaoPrazosTjscTrt12(ano).forEach(f => feriados.add(f)));
    confirmado = true;
  }
  return { feriados, confirmado };
}

function diaSemanaUTC(dateStr) { return new Date(dateStr + 'T00:00:00Z').getUTCDay(); }
function ehDiaUtil(dateStr, feriados) {
  const dw = diaSemanaUTC(dateStr);
  return dw !== 0 && dw !== 6 && !feriados.has(dateStr);
}
function proximoDiaUtil(dateStr, feriados) {
  let d = dateStr;
  while (!ehDiaUtil(d, feriados)) d = addDays(d, 1);
  return d;
}
function somarDiasUteis(inicio, quantidade, feriados) {
  let cursor = inicio, restantes = quantidade;
  while (restantes > 0) {
    cursor = addDays(cursor, 1);
    if (ehDiaUtil(cursor, feriados)) restantes -= 1;
  }
  return cursor;
}
function subtrairDiasUteis(dateStr, quantidade, feriados) {
  let cursor = dateStr, restantes = quantidade;
  while (restantes > 0) {
    cursor = addDays(cursor, -1);
    if (ehDiaUtil(cursor, feriados)) restantes -= 1;
  }
  return cursor;
}
function somarDiasCorridos(inicio, quantidade, feriados) {
  return proximoDiaUtil(addDays(inicio, quantidade), feriados);
}

const item = $json;
const anoDisp = parseInt(item.data_disponibilizacao.slice(0, 4), 10);
const { feriados, confirmado } = calendarioParaTribunal(item.tribunal, [anoDisp, anoDisp + 1]);

let inicioContagem = ehDiaUtil(item.data_disponibilizacao, feriados)
  ? proximoDiaUtil(addDays(item.data_disponibilizacao, 1), feriados)
  : proximoDiaUtil(item.data_disponibilizacao, feriados);

const quantidadeDias = item.quantidade_dias || 0;
let dataFinalLegal;
if (item.regime === 'juizado_especial_dias_corridos') {
  dataFinalLegal = somarDiasCorridos(inicioContagem, quantidadeDias, feriados);
} else {
  dataFinalLegal = somarDiasUteis(inicioContagem, quantidadeDias, feriados);
}

const dataFinalInterna = subtrairDiasUteis(dataFinalLegal, 2, feriados);

let dataPrazoTribunal = null;
try {
  const detalhe = $('Detalhe do processo (data_prazo)').item.json;
  const registro = Array.isArray(detalhe) ? detalhe[0] : detalhe;
  dataPrazoTribunal = (registro && registro.data_prazo) ? registro.data_prazo : null;
} catch (e) {}

return {
  json: {
    ...item,
    calendario_confirmado: confirmado,
    inicio_contagem: inicioContagem,
    data_final_legal: dataFinalLegal,
    data_final_interna: dataFinalInterna,
    data_prazo_tribunal: dataPrazoTribunal,
    diverge_do_tribunal: !!(dataPrazoTribunal && dataPrazoTribunal !== dataFinalLegal),
  }
};

const ativos = $('Ler ATIVOS ATUAL').all();
const usuarios = $('Listar usuários do Legalmail').all().map(i => i.json);

function normalizarProcesso(s) { return (s || '').toString().replace(/\D/g, ''); }

const numeroAlvo = normalizarProcesso($json.numero_processo);
const linhaAtivo = ativos.find(l => normalizarProcesso(l.json['Nº PROCESSO']) === numeroAlvo);
const advogadoAbreviado = linhaAtivo ? linhaAtivo.json['ADVOGADA ATUAL'] : null;

let idUsuario = null;
let nomeCompleto = advogadoAbreviado;
if (advogadoAbreviado) {
  const alvo = advogadoAbreviado.trim().toLowerCase();
  let match = usuarios.find(u => (u.nome || '').trim().toLowerCase() === alvo);
  if (!match) {
    const candidatos = usuarios.filter(u => {
      const partes = (u.nome || '').trim().split(/\s+/);
      return partes[0] && partes[0].toLowerCase() === alvo;
    });
    if (candidatos.length === 1) match = candidatos[0];
  }
  if (match) {
    idUsuario = match.idusuarios;
    nomeCompleto = match.nome;
  }
}

return {
  json: {
    ...$json,
    advogado: nomeCompleto,
    id_usuario_legalmail: idUsuario,
  }
};

const linhasPrazos = $('Ler PRAZOS (todos os processos)').all();
function normalizar(s) { return (s || '').toString().replace(/\D/g, ''); }
const conhecidos = new Set(linhasPrazos.map(l => normalizar(l.json['Nº DO PROCESSO'])));
const numeroNormalizado = normalizar($json.numero_processo);
return {
  json: {
    ...$json,
    numero_processo_normalizado: numeroNormalizado,
    caso_novo: !conhecidos.has(numeroNormalizado),
  }
};
